    private static RouteStep Step(int number, string text, string hint, string completes, RouteCheck[] checks, int[] highlights, bool conditional)
        => new(number, text, hint, completes, checks, highlights, conditional);

    private static RouteCheck Gs(int amount) => new(CheckKind.GearScore, amount, System.Array.Empty<int>(), "Gear score " + amount);
    private static RouteCheck Blood(int id, string label) => new(CheckKind.VBlood, 1, new[] { id }, label);
    private static RouteCheck Region(int[] ids, string label) => new(CheckKind.Region, 1, ids, label);
    private static RouteCheck Heart(int level) => new(CheckKind.HeartLevel, level, System.Array.Empty<int>(), "Castle Heart " + level);
    private static RouteCheck Item(int[] ids, int amount, string label, bool matchAll = false) => new(CheckKind.Item, amount, ids, label, matchAll);
    private static RouteCheck Worn(int[] ids, string label) => new(CheckKind.Equipped, 1, ids, label);
    private static RouteCheck Built(int[] ids, int amount, string label) => new(CheckKind.Placed, amount, ids, label);
    private static RouteCheck Quest(int id, string label) => new(CheckKind.Quest, 1, new[] { id }, label);
